16. 
17. import jwtDecode from "jwt-decode";
18. import { OidcMetadata, SigninResponse } from "oidc-client-ts";
19. 
20. import { IDelegatedAuthConfig } from "../client";
21. import { logger } from "../logger";
22. import { OidcError } from "./error";
23. 
24. /**
25.  * re-export for backwards compatibility
26.  * @deprecated use OidcError
27.  */
28. export { OidcError as OidcDiscoveryError };
29. 
30. export type ValidatedIssuerConfig = {
31.     authorizationEndpoint: string;
32.     tokenEndpoint: string;
33.     registrationEndpoint?: string;
34. };
35. 
36. /**
37.  * Validates MSC2965 m.authentication config
38.  * Returns valid configuration
39.  * @param wellKnown - client well known as returned from ./well-known/client/matrix
40.  * @returns config - when present and valid
41.  * @throws when config is not found or invalid
42.  */
43. export const validateWellKnownAuthentication = (authentication?: IDelegatedAuthConfig): IDelegatedAuthConfig => {
44.     if (!authentication) {
45.         throw new Error(OidcError.NotSupported);
46.     }
47. 
48.     if (
49.         typeof authentication.issuer === "string" &&
50.         (!authentication.hasOwnProperty("account") || typeof authentication.account === "string")
51.     ) {
52.         return {
53.             issuer: authentication.issuer,
54.             account: authentication.account,
55.         };
56.     }
57. 
58.     throw new Error(OidcError.Misconfigured);
59. };
60. 
61. const isRecord = (value: unknown): value is Record<string, unknown> =>
62.     !!value && typeof value === "object" && !Array.isArray(value);
63. const requiredStringProperty = (wellKnown: Record<string, unknown>, key: string): boolean => {
64.     if (!wellKnown[key] || !optionalStringProperty(wellKnown, key)) {
65.         logger.error(`Missing or invalid property: ${key}`);
66.         return false;
67.     }
68.     return true;
69. };
70. const optionalStringProperty = (wellKnown: Record<string, unknown>, key: string): boolean => {
71.     if (!!wellKnown[key] && typeof wellKnown[key] !== "string") {
72.         logger.error(`Invalid property: ${key}`);
73.         return false;
74.     }
75.     return true;
76. };
77. const requiredArrayValue = (wellKnown: Record<string, unknown>, key: string, value: any): boolean => {
78.     const array = wellKnown[key];
79.     if (!array || !Array.isArray(array) || !array.includes(value)) {
80.         logger.error(`Invalid property: ${key}. ${value} is required.`);
81.         return false;
82.     }
83.     return true;
84. };
85. 
86. /**
87.  * Validates issuer `.well-known/openid-configuration`
88.  * As defined in RFC5785 https://openid.net/specs/openid-connect-discovery-1_0.html
89.  * validates that OP is compatible with Element's OIDC flow
90.  * @param wellKnown - json object
91.  * @returns valid issuer config
92.  * @throws Error - when issuer config is not found or is invalid
93.  */
94. export const validateOIDCIssuerWellKnown = (wellKnown: unknown): ValidatedIssuerConfig => {
95.     if (!isRecord(wellKnown)) {
96.         logger.error("Issuer configuration not found or malformed");
97.         throw new Error(OidcError.OpSupport);
98.     }
99. 
100.     const isInvalid = [
101.         requiredStringProperty(wellKnown, "authorization_endpoint"),
102.         requiredStringProperty(wellKnown, "token_endpoint"),
103.         requiredStringProperty(wellKnown, "revocation_endpoint"),
104.         optionalStringProperty(wellKnown, "registration_endpoint"),
105.         requiredArrayValue(wellKnown, "response_types_supported", "code"),
106.         requiredArrayValue(wellKnown, "grant_types_supported", "authorization_code"),
107.         requiredArrayValue(wellKnown, "code_challenge_methods_supported", "S256"),
108.     ].some((isValid) => !isValid);
109. 
110.     if (!isInvalid) {
111.         return {
112.             authorizationEndpoint: wellKnown["authorization_endpoint"],
113.             tokenEndpoint: wellKnown["token_endpoint"],
114.             registrationEndpoint: wellKnown["registration_endpoint"],
115.         } as ValidatedIssuerConfig;
116.     }
117. 
118.     logger.error("Issuer configuration not valid");
119.     throw new Error(OidcError.OpSupport);
120. };
121. 
122. /**
123.  * Metadata from OIDC authority discovery
124.  * With validated properties required in type
125.  */
126. export type ValidatedIssuerMetadata = Partial<OidcMetadata> &
127.     Pick<
128.         OidcMetadata,
129.         | "issuer"
130.         | "authorization_endpoint"
131.         | "token_endpoint"
132.         | "registration_endpoint"
133.         | "revocation_endpoint"
134.         | "response_types_supported"
135.         | "grant_types_supported"
136.         | "code_challenge_methods_supported"
137.     >;
138. 
139. /**
140.  * Wraps validateOIDCIssuerWellKnown in a type assertion
141.  * that asserts expected properties are present
142.  * (Typescript assertions cannot be arrow functions)
143.  * @param metadata - issuer openid-configuration response
144.  * @throws when metadata validation fails
145.  */
146. export function isValidatedIssuerMetadata(
147.     metadata: Partial<OidcMetadata>,
148. ): asserts metadata is ValidatedIssuerMetadata {
149.     validateOIDCIssuerWellKnown(metadata);
150. }
151. 
152. /**
153.  * Standard JWT claims.
154.  *
155.  * @see https://datatracker.ietf.org/doc/html/rfc7519#section-4.1
156.  */
157. interface JwtClaims {
158.     [claim: string]: unknown;
159.     /** The "iss" (issuer) claim identifies the principal that issued the JWT. */
160.     iss?: string;
161.     /** The "sub" (subject) claim identifies the principal that is the subject of the JWT. */
162.     sub?: string;
163.     /** The "aud" (audience) claim identifies the recipients that the JWT is intended for. */
164.     aud?: string | string[];
165.     /** The "exp" (expiration time) claim identifies the expiration time on or after which the JWT MUST NOT be accepted for processing. */
166.     exp?: number;
167.     // unused claims excluded
168. }
169. interface IdTokenClaims extends JwtClaims {
170.     nonce?: string;
171. }
172. 
173. const decodeIdToken = (token: string): IdTokenClaims => {
174.     try {
175.         return jwtDecode<IdTokenClaims>(token);
176.     } catch (error) {
177.         logger.error("Could not decode id_token", error);
178.         throw error;
179.     }
180. };
181. 
182. /**
183.  * Validate idToken
184.  * https://openid.net/specs/openid-connect-core-1_0.html#IDTokenValidation
185.  * @param idToken - id token from token endpoint
186.  * @param issuer - issuer for the OP as found during discovery
187.  * @param clientId - this client's id as registered with the OP
188.  * @param nonce - nonce used in the authentication request
189.  * @throws when id token is invalid
190.  */
191. export const validateIdToken = (idToken: string | undefined, issuer: string, clientId: string, nonce: string): void => {
192.     try {
193.         if (!idToken) {
194.             throw new Error("No ID token");
195.         }
196.         const claims = decodeIdToken(idToken);
197. 
