136.     metadata,
137.     redirectUri,
138.     clientId,
139.     homeserverUrl,
140.     identityServerUrl,
141.     nonce,
142.     prompt,
143.     urlState,
144. }: {
145.     clientId: string;
146.     metadata: ValidatedIssuerMetadata;
147.     homeserverUrl: string;
148.     identityServerUrl?: string;
149.     redirectUri: string;
150.     nonce: string;
151.     prompt?: string;
152.     urlState?: string;
153. }): Promise<string> => {
154.     const scope = generateScope();
155.     const oidcClient = new OidcClient({
156.         ...metadata,
157.         client_id: clientId,
158.         redirect_uri: redirectUri,
159.         authority: metadata.issuer,
160.         response_mode: "query",
161.         response_type: "code",
162.         scope,
163.         stateStore: new WebStorageStateStore({ prefix: "mx_oidc_", store: window.sessionStorage }),
