209.     code: string,
210.     state: string,
211. ): Promise<{
212.     oidcClientSettings: IDelegatedAuthConfig & { clientId: string };
213.     tokenResponse: BearerTokenResponse;
214.     homeserverUrl: string;
215.     idTokenClaims: IdTokenClaims;
216.     identityServerUrl?: string;
217. }> => {
218.     /**
219.      * Element Web strips and changes the url on starting the app
220.      * Use the code and state from query params to rebuild a url
221.      * so that oidc-client can parse it
222.      */
223.     const reconstructedUrl = new URL(window.location.origin);
224.     reconstructedUrl.searchParams.append("code", code);
225.     reconstructedUrl.searchParams.append("state", state);
226. 
227.     // set oidc-client to use our logger
228.     Log.setLogger(logger);
229.     try {
230.         const response = new SigninResponse(reconstructedUrl.searchParams);
231. 
232.         const stateStore = new WebStorageStateStore({ prefix: "mx_oidc_", store: window.sessionStorage });
233. 
234.         // retrieve the state we put in storage at the start of oidc auth flow
235.         const stateString = await stateStore.get(response.state!);
236.         if (!stateString) {
237.             throw new Error(OidcError.MissingOrInvalidStoredState);
238.         }
239. 
240.         // hydrate the sign in state and create a client
241.         // the stored sign in state includes oidc configuration we set at the start of the oidc login flow
242.         const signInState = SigninState.fromStorageString(stateString);
243.         const client = new OidcClient({ ...signInState, stateStore });
244. 
245.         // validate the code and state, and attempt to swap the code for tokens
246.         const signinResponse = await client.processSigninResponse(reconstructedUrl.href);
247. 
248.         // extra values we stored at the start of the login flow
249.         // used to complete login in the client
250.         const userState = signinResponse.userState;
251.         validateStoredUserState(userState);
252. 
253.         // throws when response is invalid
254.         validateBearerTokenResponse(signinResponse);
255.         // throws when token is invalid
256.         validateIdToken(signinResponse.id_token, client.settings.authority, client.settings.client_id, userState.nonce);
257.         const normalizedTokenResponse = normalizeBearerTokenResponseTokenType(signinResponse);
258. 
259.         return {
260.             oidcClientSettings: {
261.                 clientId: client.settings.client_id,
262.                 issuer: client.settings.authority,
263.             },
264.             tokenResponse: normalizedTokenResponse,
265.             homeserverUrl: userState.homeserverUrl,
266.             identityServerUrl: userState.identityServerUrl,
267.             idTokenClaims: signinResponse.profile,
268.         };
269.     } catch (error) {
270.         logger.error("Oidc login failed", error);
271.         const errorType = (error as Error).message;
272. 
273.         // rethrow errors that we recognise
274.         if (Object.values(OidcError).includes(errorType as any)) {
275.             throw error;
276.         }
277.         throw new Error(OidcError.CodeExchangeFailed);
278.     }
279. };
